function legacySavedJobs(){return (D.legacyJobs||[]).filter(j=>!savedDetails[j.id]&&(saved.includes(j.id)||Object.hasOwn(states,j.id))).map(j=>{const archived={...j,kind:'archived',researchCheckedAt:j.researchCheckedAt||D.checkedAt};delete archived.rank;return archived})}
