function intro(title,subtitle,eyebrow='YOUR CAREER, CONSIDERED'){return `<div class="eyebrow">${esc(eyebrow)}</div><div class="intro"><div><h1>${esc(title)}</h1><p>${subtitle}</p></div></div>`}
function render(){
 const active=document.activeElement,insideMain=$('#main').contains?.(active),focusName=insideMain?active?.name:null,focusNodeID=insideMain?active?.id:null,selection=insideMain&&typeof active?.selectionStart==='number'?[active.selectionStart,active.selectionEnd]:null,focusKey=active?.dataset?.save?'save':active?.dataset?.job?'job':null,focusID=focusKey?active.dataset[focusKey]:null;
 $('#view-name').textContent=views[view];$('#saved-count').textContent=saved.length;$('#top-count').textContent=D.jobs.length;
 $$('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 const pages={shortlist:shortlistPage,live:livePage,saved:savedPage,profile:profilePage,salary:salaryPage,plan:planPage};
 $('#main').innerHTML=pages[view](); if(['shortlist','live','saved'].includes(view))renderList();
 updateSearchButtons();if(insideMain&&(focusNodeID||focusName)){const next=focusNodeID?document.getElementById(focusNodeID):$$('[name]').find(x=>x.name===focusName);next?.focus?.({preventScroll:true});if(selection)next?.setSelectionRange?.(...selection)}else if(insideMain&&focusID){const next=$$('[data-'+focusKey+']').find(x=>x.dataset[focusKey]===focusID);(next||$('#main')).focus({preventScroll:true})}
}
function updateSearchButtons(){$$('.new-search').forEach(b=>{b.disabled=busy||!P.countrySupported(profile);b.innerHTML=(busy?'<span class="spinner"></span>':'<span aria-hidden="true">✧</span>')+(busy?' Searching employers…':' Find new openings')})}
function toolbar(){const options=(rows,current)=>rows.map(([value,label])=>`<option value="${value}" ${value===current?'selected':''}>${label}</option>`).join('');return `<div class="toolbar"><label class="searchbox"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="Search these opportunities" placeholder="Search roles, companies or skills" value="${esc(query)}"></label><select id="filter" aria-label="Filter opportunities">${options([['all','All opportunities'],['healthcare','Healthcare roles'],['leadership','Leadership roles'],['riyadh','Riyadh'],['open','Not past deadline']],filter)}</select><select id="sort" aria-label="Sort opportunities">${options([['title','Role title (A–Z)'],['deadline','Closing soon'],['recent','Recently posted']],sort)}</select></div>`}
function criteriaSummary(){const floor=Number(profile.minimumMonthlySAR)>0,p=P.preferences(profile);return `<div class="criteria-summary"><div><strong>Your local discovery preferences</strong><p>${esc(p.country?P.countryLabel(p.country):'Any covered country')} · ${esc(p.city||'Any city in that scope')}${p.role?' · Role words: '+esc(p.role):''} · ${floor?'Minimum monthly pay SAR '+money(Number(profile.minimumMonthlySAR))+'; pay basis to confirm':'No minimum pay set'}${floor?' · '+(profile.unknownSalary==='hide'?'Hide unverified pay':'Show unverified pay'):''}</p><small>Six limited Saudi-oriented sources only. Preferences filter returned rows on this device; they are not sent in searches. Saved roles and application history remain available.</small></div><button class="text-button" data-view="profile">Edit profile</button></div>`}
function criteriaTags(j){const c=P.criteriaFor(j,profile);return `${!P.countrySupported(profile)?'<span class="tag warn">Outside current country coverage</span>':''}${c.city==='conditional'?'<span class="tag warn">Confirm Riyadh assignment</span>':c.city==='outside'?'<span class="tag warn">Outside preferred city</span>':c.city==='text'?'<span class="tag warn">City text match — confirm worksite</span>':''}${c.salary==='unverified'?'<span class="tag warn">Salary unverified — confirm your minimum</span>':''}`}
function shortlistPage(){return `${intro('Your next career step.','Start with your own experience, review the available sources and keep a record of your applications.','YOUR CAREER WORKSPACE')}<section class="card"><h2>Start here</h2><p>Your profile starts empty. Every field is optional. Add only details you want to keep on this device.</p><div class="dialog-buttons"><button class="primary" data-view="profile">Set up your profile</button><button class="secondary" data-view="live">Review available job sources</button><button class="secondary" data-view="saved">Open saved records</button></div></section><section class="card" style="margin-top:20px"><h2>Current live coverage</h2><p>Live search checks bounded samples from six selected Saudi employer sources for supply-chain, procurement and performance roles. Countries and role families outside that scope are not supported by live search in this build.</p><p>Availability of the app in a country does not establish job coverage there. Existing saved jobs, application records and your entered profile remain on this device. Earlier researched roles are retained only when connected to existing records; they are not new recommendations.</p></section>${D.jobs.length?`${criteriaSummary()}${toolbar()}<div id="result-count" role="status" aria-live="polite"></div><div class="job-list" id="job-list"></div>`:''}` }
function row(j,index){const expired=C.isExpired(j.closes),isSaved=saved.includes(j.id);return `<article class="job-row"><span class="rank">${String(view==='shortlist'?(j.rank||index+1):index+1).padStart(2,'0')}</span><span class="company-logo" aria-hidden="true">${esc(j.initials||glyph(j.company))}</span><div><button class="job-title" data-job="${esc(j.id)}">${esc(j.title)}</button><div class="job-meta">${esc(j.company)} · ${esc(j.location)}${j.mode&&j.mode!=='Not stated'?' · '+esc(j.mode):''}</div><p class="job-summary">${j.kind==='archived'?'Historical assessment: ':''}${esc(j.summary)}</p><div class="tags"><span class="tag ${expired?'warn':'good'}">${expired?'Past listed deadline':j.kind==='archived'?'Archived research':j.kind==='live'?'Employer listing':'Research '+date(j.researchCheckedAt||D.checkedAt)}</span><span class="tag ${/stretch|fallback/.test(j.fit)?'warn':''}">${j.kind==='archived'?'Earlier assessment: ':''}${esc(j.fit)}</span>${criteriaTags(j)}<span class="tag">${j.kind==='archived'?'Archived salary evidence':j.rank?'Salary undisclosed in research':'Salary not checked'}</span>${unrefreshed(j)?'<span class="tag warn">Not refreshed — previous result</span>':''}${j.lastCheckedAt?`<span class="tag">Employer checked ${date(j.lastCheckedAt)}</span>`:''}${j.closes?`<span class="tag">${expired?'Listed deadline':'Closes'} ${deadline(j.closes)}</span>`:''}${states[j.id]?`<span class="tag">${esc(states[j.id])}</span>`:''}</div></div><div class="job-actions"><button class="secondary" data-job="${esc(j.id)}">View role</button><button class="save-button ${isSaved?'saved':''}" data-save="${esc(j.id)}" aria-label="${isSaved?'Unsave':'Save'} ${esc(j.title)}" aria-pressed="${isSaved}">${isSaved?'♥':'♡'}</button></div></article>`}
function renderList(){let list=view==='shortlist'?D.jobs.map(j=>jobById(j.id)):view==='live'?(live?.jobs||[]).map(j=>jobById(j.id)):allJobs().filter(j=>saved.includes(j.id));
 const discovery=view==='shortlist'||view==='live';if(discovery&&!P.countrySupported(profile)){if($('#result-count'))$('#result-count').textContent='Country outside current source coverage';if($('#job-list'))$('#job-list').innerHTML=`<div class="empty"><h2>Live sources do not cover ${esc(P.countryLabel(P.preferences(profile).country))}.</h2><p>This build checks bounded samples from six selected Saudi-oriented employer sources. Unsupported coverage does not mean there are no jobs in your country. Your saved roles and application records remain available.</p><button class="secondary" data-view="profile">Review local preferences</button></div>`;return}if(discovery)list=list.filter(j=>P.criteriaFor(j,profile).included);
 const salaryHidden=discovery&&Number(profile.minimumMonthlySAR)>0&&profile.unknownSalary==='hide';
 const term=query.toLowerCase().trim();list=list.filter(j=>!term||[j.title,j.company,j.location,j.summary,...(j.gaps||[])].join(' ').toLowerCase().includes(term));
 list=list.filter(j=>filter==='all'||filter==='healthcare'&&(j.healthcare===true||j.healthcare==null&&/healthcare|medical/i.test(j.title))||filter==='leadership'&&(j.leadership||/manager|director|head/i.test(j.title))||filter==='riyadh'&&C.riyadhCity(j.location)!=='outside'||filter==='open'&&!C.isExpired(j.closes));
 if(sort==='deadline')list.sort((a,b)=>(C.dateSortTime(a.closes,true)??Infinity)-(C.dateSortTime(b.closes,true)??Infinity));else if(sort==='recent')list.sort((a,b)=>(C.dateSortTime(b.posted)??-Infinity)-(C.dateSortTime(a.posted)??-Infinity));else list.sort((a,b)=>a.title.localeCompare(b.title)||a.company.localeCompare(b.company)||a.id.localeCompare(b.id));
 if($('#result-count'))$('#result-count').textContent=list.length+' '+(list.length===1?'opportunity':'opportunities')+(discovery&&Number(profile.minimumMonthlySAR)>0&&list.length?' · salary unverified':'');
 if($('#job-list')&&busy&&view==='live'&&!list.length){$('#job-list').innerHTML='<div class="empty"><span class="spinner"></span><h2>Searching employer boards…</h2><p>Checking published roles, Saudi locations and application status.</p></div>';return}if($('#job-list'))$('#job-list').innerHTML=list.length?list.map(row).join(''):`<div class="empty"><h2>${salaryHidden?'Monthly pay is not verified':query||filter!=='all'?'No matching opportunities':view==='saved'?'Make a shortlist of your own.':'No matching openings yet.'}</h2><p>${salaryHidden?'Current listings have no verified comparable monthly pay, and your criteria hide unverified salaries. This does not mean there are no vacancies. Edit your profile to review these leads while confirming your minimum.':query||filter!=='all'?'Try a broader search or choose all opportunities.':view==='saved'?'Tap the heart on any role to keep it here. Saved roles and progress stay on this device.':'These local filters apply only to the six limited Saudi-oriented sources and their supported role families. Adjust your city or role words, or search those sources. Empty results do not establish that no jobs exist elsewhere; errors are shown separately.'}</p>${salaryHidden?'<button class="secondary" data-view="profile">Edit profile</button>':view==='live'?'<button class="primary" data-action="refresh">Search employers</button>':''}</div>`;
}
function livePage(){return `${intro('Find the next opportunity.','Search bounded samples from six selected Saudi-oriented employer sources for supply-chain, procurement and performance roles. Other countries and role families are not covered.','LIVE EMPLOYER SEARCH')}<button class="primary" data-action="refresh" ${busy||!P.countrySupported(profile)?'disabled':''}>${busy?'<span class="spinner"></span> Searching…':'Find new openings'}</button><p class="notice">Alcon · J&J · Roche · Novartis · GSK · BD. No sign-in or CV is sent to search. Results are new leads, not a new researched shortlist.</p>${liveError?`<div class="callout"><div><strong>Search could not finish</strong><p>${esc(liveError)} Your saved records and previous results are preserved.</p>${failedSources.map(s=>`<p>${esc(s.name)}: ${esc(s.error||'Unavailable')}</p>`).join('')}</div></div>`:''}${coverageWarning?`<div class="callout"><div><strong>Search coverage is incomplete</strong><p>${esc(coverageWarning)}</p></div></div>`:''}${live?`<div class="section-line"><h2>${liveError?'Previous successful search':'Latest search'}</h2><span>${esc(P.displayDate(live.checkedAt,profile,true))}</span></div><details class="disclosure"><summary>${live.sources.filter(s=>s.ok).length} of ${live.sources.length} employers responded · view search coverage</summary>${live.sources.map(s=>`<div class="source-row"><strong>${esc(s.name)}</strong><span class="${s.ok?'':'error'}">${s.ok?`${esc(s.count??0)} matching · ${esc(s.scanned??'—')} scanned${s.limited?' · bounded sample':''}${s.error?' · '+esc(s.error):s.detailErrors?' · '+esc(s.detailErrors)+' details unavailable':''}`:esc(s.error||'Unavailable')}</span></div>`).join('')}<p>Searches a bounded sample of selected boards. Title filtering can miss suitable roles; multiple-location and missing-detail jobs may be excluded. Source failures never mean an employer has no jobs. No coverage of the entire Saudi market or other countries is implied. Unsupported coverage is not evidence that there are no jobs there.</p></details>`:''}${criteriaSummary()}${toolbar()}<div class="section-line"><h2>New leads to review</h2><span id="result-count" role="status" aria-live="polite"></span></div><div class="job-list" id="job-list"></div>`}
function savedPage(){return `${intro('The ones worth pursuing.','Your selected opportunities, with application progress in one place.','SAVED OPPORTUNITIES')}<p class="notice">Saved on this device only. Website, iPhone and Mac progress do not sync.</p>${toolbar()}<div class="section-line"><h2>Your shortlist</h2><span id="result-count" role="status" aria-live="polite"></span></div><div class="job-list" id="job-list"></div>`}
function profilePage(){const p=P.preferences(profileDraft);return `${intro('Start with what is true.','No biography or qualifications are assumed. Every field is optional.','YOUR PROFILE')}<section class="card" style="margin-top:20px"><h2>Add your own details</h2><p>These stay in this browser or app on this device. Your professional details support application notes and experience warnings. Preferences filter only the available rows; no personal preferences are sent to employers or the search service.</p><form id="profile-form"><fieldset class="criteria-fields"><legend>Country, city and role preferences</legend><p>Live search covers bounded samples from six selected Saudi-oriented employer sources for supply-chain, procurement and performance roles. Choosing another country or role does not add source coverage. Saved records are never hidden by these preferences.</p><label class="field">Country or region<select name="targetCountry">${countryOptions(p.country)}</select></label><label class="field">City text, if relevant<input name="targetCity" maxlength="100" value="${esc(p.city)}" placeholder="Any city in the selected scope"><small>Filters the location text of returned listings. Confirm the worksite with the employer; locations and spellings may be incomplete.</small></label><label class="field">Role keywords<input name="roleKeywords" maxlength="200" value="${esc(p.role)}" placeholder="Any role in current source coverage"><small>Every space-separated word must appear in a returned role title or subtitle. This local text filter does not establish eligibility or add role families.</small></label></fieldset><fieldset class="criteria-fields"><legend>Planning and display</legend><label class="field">Planning currency<select name="planningCurrency">${currencyOptions(p.currency)}</select><small>Default for your local offer calculator only. Existing SAR salary criteria and source evidence stay SAR. No currency conversion is performed.</small></label><label class="field">Planning amount period<select name="planningPayPeriod">${option('monthly','Monthly fixed amounts',p.period)}${option('annual','Annual fixed amounts',p.period)}</select></label><label class="field">Display time zone<select name="displayTimeZone">${zoneOptions(profileValue(profileDraft,'displayTimeZone'))}</select><small>Applies to timestamps with an explicit offset. Published date-only deadlines keep their source date. Existing application-date validation still uses the Riyadh day; dates are never shifted.</small></label></fieldset><fieldset class="criteria-fields"><legend>Salary filter for current Saudi sources</legend><label class="field">Minimum monthly pay, SAR<input name="minimumMonthlySAR" type="text" inputmode="decimal" maxlength="32" placeholder="No minimum set" value="${esc(profileDraft.minimumMonthlySAR??'')}" aria-describedby="minimum-pay-help"><small id="minimum-pay-help">Whole SAR from 0 to 1,000,000; blank or zero means no minimum. This existing filter stays monthly SAR regardless of planning currency. Confirm basic salary versus fixed package; current listings have no verified comparable pay.</small></label><label class="field">Listings with unverified pay<select id="unknown-salary" name="unknownSalary" ${Number(C.canonicalMinimumSAR(profileDraft.minimumMonthlySAR??''))>0?'':'disabled'}><option value="show" ${profileDraft.unknownSalary!=='hide'?'selected':''}>Show and confirm my minimum</option><option value="hide" ${profileDraft.unknownSalary==='hide'?'selected':''}>Hide from discovery</option></select></label></fieldset><div class="inline-fields"><label class="field">Relevant years of experience<input name="years" type="number" min="0" max="60" step="0.5" placeholder="Not yet provided" value="${esc(profileDraft.years??'')}"></label><label class="field">Degree and certifications<input name="degree" maxlength="300" placeholder="Your exact qualification" value="${esc(profileDraft.degree||'')}"></label></div><label class="field">Tools and responsibilities<textarea name="skills" maxlength="3000" placeholder="Your own experience">${esc(profileDraft.skills||'')}</textarea></label><label class="field">Achievements you can substantiate<textarea name="achievements" maxlength="5000" placeholder="What changed, over what period, and your contribution. Avoid confidential employer data.">${esc(profileDraft.achievements||'')}</textarea></label><p class="notice">Country, city, role, planning and display preferences are excluded from exported application notes and search requests.</p><button class="primary" type="submit">Save on this device</button></form></section>`}
function salaryPage(){return `${intro('Negotiate the whole package.','Salary was not disclosed in the researched listings when checked. Compare scope and a written offer before deciding that a role pays more.','SALARY & NEGOTIATION')}<div class="callout"><span class="symbol">▥</span><div><strong>Salary potential is not an offer.</strong><p>The figures below are historical Saudi market benchmarks, not job-specific estimates or guaranteed pay. The ${link('https://www.hays.ae/salary-guide/saudi-arabia-salary-guide','Hays 2026 guide')} exists; its detailed tables were not available without a contact form.</p></div></div><div class="grid-two"><section class="card"><div class="card-label">HISTORICAL 2025 · SUPPLY CHAIN MANAGER</div><div class="salary-value">SAR 30,000–45,000</div><p>Total fixed monthly package.<br>Hays data as of Q4 2024.</p></section><section class="card"><div class="card-label">HISTORICAL 2025 · PROCUREMENT MANAGER</div><div class="salary-value">SAR 30,000–50,000</div><p>Total fixed monthly package.<br>Hays data as of Q4 2024.</p></section></div><p class="notice">${link(D.benchmarks[0].url,'Hays Saudi Arabia Salary Guide 2025, p.38')}. Broad market, not healthcare-specific. Fixed allowances are included; these are not basic-salary ranges. Director ranges are not a target unless your leadership experience supports that level.</p><details class="disclosure"><summary>Cross-check with another salary guide</summary><p>${link(D.benchmarks[1].url,'The Professionals Salary Guide 2025')} reports Supply & Demand Manager at SAR 30,220 / 42,866 / 53,710 monthly for the 25th percentile / median / 75th percentile (p.49). Methodology (p.15): basic salary + housing + transportation. Different role definitions and samples mean the guides are context, not interchangeable quotes.</p></details><section class="card" style="margin-top:24px"><h2>Compare your entered package</h2><p>Choose the currency and period for your own amounts. Changing either clears the calculator, so amounts are never silently relabeled. No exchange rates, taxes or deductions are applied; historical Saudi evidence above stays SAR.</p><form id="package-form"><div class="inline-fields"><label class="field">Currency<select name="currency">${currencyOptions(P.preferences(profile).currency)}</select></label><label class="field">Fixed amount period<select name="period">${option('monthly','Monthly',P.preferences(profile).period)}${option('annual','Annual',P.preferences(profile).period)}</select></label></div><div class="inline-fields"><label class="field">Basic pay for chosen period<input name="base" type="text" inputmode="decimal" maxlength="32" value=""></label><label class="field">Fixed allowances for chosen period<input name="allowances" type="text" inputmode="decimal" maxlength="32" value=""></label></div><label class="field">Target annual bonus (not guaranteed)<input name="bonus" type="text" inputmode="decimal" maxlength="32" value=""></label><p class="notice">Blank amounts count as zero. Up to two decimal places; use a comma to group thousands and a dot for decimals. Arabic digits and separators are accepted. Limits: 1,000,000 per fixed component and 10,000,000 for annual bonus, in the selected currency. Values with more precision are rejected rather than rounded.</p><div class="highlight-note" id="package-result" role="status" aria-live="polite" aria-atomic="true"><p>Choose a currency and enter your own amounts to calculate. These temporary entries are not saved.</p></div></form></section><section class="card" style="margin-top:20px"><h2>The conversation to have</h2><ol class="steps"><li><strong>Get the budgeted range early.</strong><span>“What is the approved grade and total fixed monthly package for this position?”</span></li><li><strong>Price the responsibility.</strong><span>Clarify direct reports, procurement authority, spend responsibility, KPI ownership and delivery expectations.</span></li><li><strong>Separate each component.</strong><span>Ask for basic, fixed allowances, target bonus and payout conditions, medical coverage, leave and any relocation support in writing.</span></li><li><strong>Negotiate with evidence.</strong><span>Use verified service, waste, stockout, cost or supplier outcomes. Do not invent your current salary or competing offers.</span></li><li><strong>Compare the full move.</strong><span>Account for commute, city costs, hours, probation, notice period and progression. Obtain the final written terms before making a commitment.</span></li></ol></section>`}
const planItems=[['profile','Confirm your professional record','Your work dates, responsibilities, relevant experience and any qualifications you choose to include.'],['evidence','Prepare credible achievement examples','Describe your own actions and outcomes with accurate, shareable information.'],['cv','Prepare your CV materials','For each application, tailor a version using your own experience and qualifications.'],['priority','Review selected role requirements','Before each application, check that role’s experience, location, work eligibility and other requirements.'],['deadline','Check selected deadlines','Before each application, check that role’s listed deadline and current vacancy status directly with the employer.'],['review','Review each application yourself','Verify all fields, uploaded files and claims. Applications are never automatically submitted by this app.']];
function planPage(){return `${intro('A thoughtful application beats ten generic ones.','Focus first on evidence, then on a small number of well-matched roles.','YOUR APPLICATION PLAN')}${attentionSection()}<div class="grid-two"><section class="card"><h2>Your preparation checklist</h2><p>Checked items record your preparation on this device. Recheck the requirements, dates and materials for each application.</p>${planItems.map(([id,t,s])=>`<label class="check-row"><input type="checkbox" id="check-${id}" data-check="${id}" ${checklist[id]?'checked':''}><span>${esc(t)}<small>${esc(s)}</small></span></label>`).join('')}</section><section class="card"><div class="card-label">POSITIONING TO TEST</div><h2>Explain your contribution.</h2><p>Choose an example from your own work, study or projects. Explain what you did, the outcome and what evidence supports it. Do not inherit another person’s career history or claim responsibility you did not have.</p><div class="highlight-note"><p>“In [context], I contributed [specific action]. The result was [supported outcome] over [period]. My responsibility was [actual scope].”</p></div><p>Replace every bracket with facts you can substantiate. If you only reported the result, say so.</p><button class="secondary" data-action="export" style="margin-top:18px">Download my application notes</button></section></div><div class="section-line"><h2>Application records</h2><span>Manually maintained</span></div>${retainedJobs().filter(j=>states[j.id]&&states[j.id]!=='Not started'||meaningfulRecord(j.id)).map((j,i)=>row(j,i)).join('')||'<div class="empty"><h2>No applications marked yet.</h2><p>Open a role and update its application status after you complete a step.</p><button class="secondary" data-view="shortlist">Review your opportunities</button></div>'}`}
let dialogReturn=null,dialogJob=null;
function rememberDialogOpener(){if(!$('#job-dialog').open){const e=document.activeElement;dialogReturn={element:e,job:e?.dataset?.job,save:e?.dataset?.save}}}
const dialogNotice=()=>`<p id="dialog-notice" class="dialog-notice" role="status" aria-live="polite" ${storageNotice?'':'hidden'}>${esc(storageNotice)}</p>`;
function openJob(id){rememberDialogOpener();const j=jobById(id);if(!j)return;dialogJob=j;const exp=C.isExpired(j.closes);const years=profile.years;const gap=years!==undefined&&years!==''&&j.minYears&&Number(years)<j.minYears;
 $('#job-dialog').innerHTML=`<div class="dialog-top"><span class="muted" style="font-size:.8rem">${j.rank?'PRIORITY '+String(j.rank).padStart(2,'0'):j.kind==='archived'?'ARCHIVED ROLE':'NEW EMPLOYER LEAD'} · ${esc(j.company)}</span><button class="icon-button" data-action="close" aria-label="Close role details">×</button></div><div class="dialog-body"><span class="tag ${exp?'warn':'good'}">${exp?'Past listed deadline':j.kind==='archived'?'Archived research':j.kind==='live'?'Live search result':'Research '+date(j.researchCheckedAt||D.checkedAt)}</span><h2 id="dialog-title">${esc(j.title)}</h2><p class="muted">${esc(j.company)} · ${esc(j.location)}${j.mode&&j.mode!=='Not stated'?' · '+esc(j.mode):''}<br>${esc(j.subtitle||'')}</p><div class="tags">${criteriaTags(j)}<span class="tag">Posted ${date(j.posted)}</span><span class="tag">${j.closes?'Closes '+deadline(j.closes):'No closing date published'}</span><span class="tag">${j.kind==='archived'?'Archived salary evidence':j.rank?'Salary undisclosed in research':'Salary not checked'}</span></div>${gap?`<div class="callout"><div><strong>Your entered experience is below this requirement.</strong><p>You entered ${esc(years)} relevant years. This listing asks for ${j.minYears}+; review eligibility before applying.</p></div></div>`:''}${unrefreshed(j)?'<p class="notice">Not refreshed in the latest attempt. This previous result is retained because its employer search was unavailable.</p>':''}${j.lastCheckedAt?`<p class="notice">Employer listing last checked ${date(j.lastCheckedAt)}. A past search does not guarantee the vacancy is still open.</p>`:''}${j.kind==='archived'?`<p class="notice">This role and its earlier assessment are preserved from your records. The assessment is historical evidence, not personalized advice for your current profile. Original research date: ${j.researchCheckedAt?date(j.researchCheckedAt):'unavailable'}. Recheck all requirements and availability.</p>`:''}<h3>${j.kind==='archived'?'Preserved earlier assessment':'Listing information to review'}</h3><p>${esc(j.summary)}</p><p class="notice">${esc(j.fit)}. This is not a verified personal fit score. Compare the employer requirements with your own evidence.</p><h3>What to establish first</h3><ul>${(j.gaps||['Read the complete employer requirements and confirm experience, degree, location, work eligibility and seniority.','This lead was found by title and location. It has not received the full research review of the shortlist.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Your application, step by step</h3><ol class="steps">${(j.steps||[['Read the official description','Confirm the position is still open and compare every mandatory requirement with your experience.'],['Tailor your evidence','Select two actual achievements that demonstrate the responsibilities. Do not invent credentials or outcomes.'],['Apply personally','Use the employer’s application route, review the form and attachments, then submit only when you are ready.'],['Keep the receipt','Save the acknowledgement and update the status below.']]).map(([t,s])=>`<li><strong>${esc(t)}</strong><span>${esc(s)}</span></li>`).join('')}</ol><h3>Application status</h3><select class="status-select" data-status="${esc(j.id)}" aria-label="Application status">${['Not started','Preparing','Applied','Interviewing','Offer received','Closed / not pursuing'].map(x=>`<option ${states[j.id]===x?'selected':''}>${x}</option>`).join('')}</select><p class="notice">This is your own tracking record. Changing it does not submit an application or contact anyone.</p>${recordEditor(j)}<div class="dialog-buttons">${link(j.applyUrl||j.url,exp?'Check employer status':states[j.id]&&states[j.id]!=='Not started'?'View employer / existing application':'Open official application','primary')}<button class="secondary" data-save="${esc(j.id)}">${saved.includes(j.id)?'Remove from saved':'Save opportunity'}</button><button class="secondary" data-draft="${esc(j.id)}">Prepare application note</button></div><p class="notice">${link(j.sourceUrl||j.url,'View source and full requirements')} · Recheck salary, deadline and eligibility directly with the employer. Application forms may change.</p></div>`;
 $('#job-dialog').insertAdjacentHTML?.('beforeend',dialogNotice());if(!$('#job-dialog').open)$('#job-dialog').showModal();
}
function toggleSaved(id){return workspaceAction(()=>{const j=jobById(id);if(!j)return;if(saved.includes(id))saved=saved.filter(x=>x!==id);else saved.push(id);savedDetails[id]=j;const savedOK=persistWorkspace();render();if($('#job-dialog').open){openJob(id);$('#job-dialog [data-save]')?.focus?.()}if(savedOK)toast(saved.includes(id)?'Saved on this device.':'Removed from saved opportunities.')})}
function noteValue(key,current,valid){
 if(blockedKeys.has(key)||failedKeys.has(key)||key==='checklist'&&Object.keys(checklistPending).length)return current;
 const latest=read(key,{});if(blockedKeys.has(key))return current;
 if(!valid(latest)){unreadable(key);return current}return latest;
}
function draft(j){const p=noteValue('profile',profile,validProfile);return `Application preparation note — ${j.title}, ${j.company}\n\nI am interested in this opportunity. I will compare the requirements with my own experience and add only claims I can substantiate.\n\nBefore using this draft, add only verified experience and results that meet these requirements:\n${(j.gaps||['Review the employer requirements.']).map(x=>'• '+x).join('\n')}\n\nMy evidence (self-entered, review for accuracy):\n${p.achievements||'[Add two accurate achievements, their measurement period and your own contribution.]'}\n\nOfficial vacancy: ${j.url}\n\nThis is an unsent preparation draft. Review and rewrite it before using it in an application.`}
function exportNotes(){if(!failedKeys.has('workspace'))syncWorkspace();const p=noteValue('profile',profile,validProfile),checks=noteValue('checklist',checklist,validChecklist);const text=`CAREER FINDER — APPLICATION NOTES\nLegacy research reference date: ${D.checkedAt}\nExported: ${new Date().toISOString()}\nLive search scope: selected Saudi employer sources and role families. Saved locally; this app does not submit applications.\n\nPROFILE (SELF-ENTERED)\nRelevant years: ${p.years??'Not provided'}\nQualifications: ${p.degree||'Not provided'}\nTools and scope: ${p.skills||'Not provided'}\nAchievements: ${p.achievements||'Not provided'}\n\n${retainedJobs(true).map(j=>`${j.title} — ${j.company}\n${j.url}\n${j.location}\n${j.kind==='archived'?'Archived research — outside the current shortlist.\n':''}Research checked: ${j.researchCheckedAt||'Not researched'}\nEmployer checked: ${j.lastCheckedAt||'Not recorded'}\nListed deadline: ${j.closes||'Not stated'}\nStatus: ${states[j.id]||'Not started'}${recordText(j.id)}\n${j.summary}\n${(j.gaps||[]).join('\n')}`).join('\n\n')}\n\nPREPARATION\n${planItems.map(([id,t])=>(checks[id]?'[x] ':'[ ] ')+t).join('\n')}\n\nChecked items record your preparation on this device. Recheck the requirements, dates and materials for each application.`;if(window.webkit?.messageHandlers?.careerSearch){showNotes(text,true);return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='Career-Finder-application-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function showNotes(text,tracking=false){rememberDialogOpener();const dialog=$('#job-dialog');dialog.innerHTML=`<div class="dialog-top"><strong id="dialog-title">Your application notes</strong><button class="icon-button" data-action="close" aria-label="Close notes">×</button></div><div class="dialog-body"><p class="notice">${tracking?'Tracking export includes your self-entered profile, receipt notes and any unsaved record drafts. Review before sharing.':'Unsent preparation draft. Review all claims before using.'}</p><label class="field">Notes<textarea id="note-text" readonly style="min-height:340px">${esc(text)}</textarea></label><button class="primary" data-action="copy-notes">Copy notes</button></div>`;dialog.insertAdjacentHTML?.('beforeend',dialogNotice());if(!dialog.open)dialog.showModal();$('#note-text')?.focus?.()}
function receiveLive(payload){return storedAction('live',()=>{
 const latest=C.normalizeLive(read('live',null));if(latest&&(!live||C.parsedDate(latest.checkedAt).time>C.parsedDate(live.checkedAt).time))live=latest;
 acceptLive(payload);
})}
function acceptLive(payload){clearTimeout(nativeTimer);busy=false;failedSources=[];coverageWarning='';const incoming=C.normalizeLive(payload);
 if(!incoming){liveError=typeof payload?.error==='string'?payload.error:'The search returned an invalid response.'}
 else if(live&&C.parsedDate(incoming.checkedAt).time<C.parsedDate(live.checkedAt).time){liveError='An older search response was ignored.'}
 else{incoming.jobs=incoming.jobs.filter(j=>j.company!=='Qiddiya'&&j.healthcare!==false&&!C.isExpired(j.closes)&&!C.isFuture(j.posted)&&C.relevance(j.title)>0);
 if(!incoming.sources.length||incoming.sources.every(s=>!s.ok)&&!incoming.jobs.length){failedSources=incoming.sources;liveError='All selected employer sources were unavailable. Try again later.'}
 else{const ids=new Set(incoming.jobs.map(j=>j.id)),failed=new Set(incoming.sources.filter(C.sourceIncomplete).map(s=>s.name));incoming.jobs.push(...(live?.jobs||[]).filter(j=>!ids.has(j.id)&&failed.has(j.company)&&!incoming.sources.some(s=>s.name===j.company&&s.excludedIds?.includes(j.id))&&!C.isExpired(j.closes)&&!C.isFuture(j.posted)&&C.relevance(j.title)>0));live=incoming;persist('live',live);const acceptedJobs=live.jobs;workspaceAction(()=>retainKnownJobs(acceptedJobs));liveError='';coverageWarning=coverageMessage(incoming)}}
 if(['live','plan','shortlist','saved'].includes(view))render();else updateSearchButtons();toast(liveError?'Search could not finish; previous results were retained.':coverageWarning?'Some employer checks were incomplete.':'Employer search finished. Review the coverage notes.')
}
window.receiveNativeJobs=receiveLive;
async function refresh(){if(busy)return;if(!P.countrySupported(profile)){go('live');toast('Live sources do not cover the selected country. Your saved records remain available.');return}busy=true;liveError='';coverageWarning='';view='live';query='';filter='all';sort='title';setMenu(false);render();$('#main').focus({preventScroll:true});
 if(window.webkit?.messageHandlers?.careerSearch){nativeTimer=setTimeout(()=>receiveLive({error:'The native search timed out. Please try again.'}),65000);window.webkit.messageHandlers.careerSearch.postMessage({action:'refresh'});return}
 try{const response=await fetch('/api/live',{headers:{Accept:'application/json'},signal:AbortSignal.timeout(65000)});if(!response.ok)throw Error('Search service returned '+response.status);receiveLive(await response.json())}catch(e){receiveLive({error:location.protocol==='file:'?'Open this website through its local server, or use the iPhone/Mac app to search live sources.':e.message||'Search is unavailable.'})}
}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a[data-view]');if(!b)return;if(b.dataset.view){go(b.dataset.view);return}if(b.dataset.job){openJob(b.dataset.job);return}if(b.dataset.save){toggleSaved(b.dataset.save);return}if(b.dataset.draft){const j=jobById(b.dataset.draft);if(j)showNotes(draft(j));return}
 switch(b.dataset.action){case'refresh':refresh();break;case'menu':setMenu(!$('#sidebar').classList.contains('open'));break;case'close-menu':setMenu(false);break;case'theme':document.body.classList.toggle('dark');syncTheme();persist('dark',document.body.classList.contains('dark'));break;case'close':$('#job-dialog').close();break;case'copy-notes':{const area=$('#note-text');try{if(navigator.clipboard)await navigator.clipboard.writeText(area.value);else{area.select();if(!document.execCommand('copy'))throw Error('copy')}toast('Notes copied. Review before using.')}catch{area.focus();area.select();toast('Select and copy the notes manually.')}break}case'reload-record':{const id=b.dataset.record;if(!recordDirty(recordDrafts[id])||confirm('Discard this unsaved application record draft and load the saved version?')){delete recordDrafts[id];openJob(id)}break}case'export':exportNotes();break}});
function captureProfileInput(target){if(target.closest?.('#profile-form')&&profileFields.includes(target.name)){profileDraft[target.name]=target.value;if(target.name==='minimumMonthlySAR')$('#unknown-salary').disabled=!(Number(C.canonicalMinimumSAR(target.value))>0)}}
function updatePackage(form){const f=new FormData(form),currency=String(f.get('currency')||''),period=String(f.get('period')||'');if(!P.currencyCodes.includes(currency)){$('#package-result').textContent='Choose a currency before calculating.';return}const result=P.packageTotals(String(f.get('base')||''),String(f.get('allowances')||''),String(f.get('bonus')||''),period);if(!result){$('#package-result').textContent='Check the amounts and period. Values must be non-negative, within the stated limits and use at most two decimal places; invalid input is not calculated.';return}$('#package-result').innerHTML=`<p>${period==='annual'?'Monthly equivalent (annual ÷ 12)':'Fixed monthly'}: <strong>${esc(amountLabel(result.monthly,currency))}</strong><br>Fixed annual: <strong>${esc(amountLabel(result.annual,currency))}</strong><br>Including target annual bonus: <strong>${esc(amountLabel(result.includingBonus,currency))}</strong></p><p class="notice">Arithmetic from your entries only. Bonus is not guaranteed. Monthly equivalents are displayed to two decimal places.</p>`}
document.addEventListener('input',e=>{captureProfileInput(e.target);captureRecordInput(e.target);if(e.target.id==='search'){query=e.target.value;renderList()}if(e.target.closest('#package-form'))updatePackage($('#package-form'))});
document.addEventListener('change',e=>{if(e.target.closest?.('#package-form')&&['currency','period'].includes(e.target.name)){for(const field of $$('#package-form input'))field.value='';$('#package-result').textContent='Calculator amounts cleared. Enter amounts in the selected currency and period.';return}captureProfileInput(e.target);captureRecordInput(e.target);if(e.target.id==='filter'){filter=e.target.value;renderList()}if(e.target.id==='sort'){sort=e.target.value;renderList()}if(e.target.dataset.check)return saveChecklist(e.target.dataset.check,e.target.checked);if(e.target.dataset.status){return workspaceAction(()=>{const id=e.target.dataset.status;if(!statusValues.includes(e.target.value))return;const j=jobById(id);if(!j)return;states[id]=e.target.value;savedDetails[id]=j;const stateOK=persistWorkspace();render();if(stateOK)toast('Application status saved on this device.')})}});
document.addEventListener('submit',e=>{if(e.target.id==='application-record-form'){e.preventDefault();return saveApplicationRecord(e.target.dataset.record)}if(e.target.id==='package-form'){e.preventDefault();return}if(e.target.id!=='profile-form')return;e.preventDefault();const f=new FormData(e.target);const next={...profileDraft,years:f.get('years')===''?'':Math.max(0,Math.min(60,Number(f.get('years')))),degree:String(f.get('degree')).slice(0,300),skills:String(f.get('skills')).slice(0,3000),achievements:String(f.get('achievements')).slice(0,5000),minimumMonthlySAR:String(f.get('minimumMonthlySAR')||''),unknownSalary:String(f.get('unknownSalary')||profileDraft.unknownSalary||'show'),preferencesVersion:'2',targetCountry:String(f.get('targetCountry')??profileValue(profileDraft,'targetCountry')),targetCity:String(f.get('targetCity')??profileValue(profileDraft,'targetCity')),roleKeywords:String(f.get('roleKeywords')??profileValue(profileDraft,'roleKeywords')),planningCurrency:String(f.get('planningCurrency')??profileValue(profileDraft,'planningCurrency')),planningPayPeriod:String(f.get('planningPayPeriod')??profileValue(profileDraft,'planningPayPeriod')),displayTimeZone:String(f.get('displayTimeZone')??profileValue(profileDraft,'displayTimeZone'))};return saveProfile(next)});
$('#job-dialog').addEventListener('close',()=>{const opener=dialogReturn;const target=opener?.element?.isConnected?opener.element:opener?.job?$$('[data-job]').find(e=>e.dataset.job===opener.job):opener?.save?$$('[data-save]').find(e=>e.dataset.save===opener.save):null;(target?.getClientRects?.().length?target:$('#main')).focus({preventScroll:true});dialogReturn=null;dialogJob=null});
$('#job-dialog').addEventListener('click',e=>{if(e.target===$('#job-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open'))setMenu(false)});
window.addEventListener?.('resize',()=>{if(!globalThis.matchMedia?.('(max-width:760px)').matches)setMenu(false)});
window.addEventListener?.('storage',e=>{if(e.key?.startsWith('ahmad-application-record-v1:')){if(dialogJob&&$('#job-dialog').open){const id=dialogJob.id,d=recordDrafts[id];if(d&&!recordDirty(d)){editApplicationRecord(id);const form=$('#application-record-form');if(form?.dataset.record===id){$('#application-date').value=recordDrafts[id].appliedAt;$('#application-receipt').value=recordDrafts[id].receiptNote;updateRecordEditor(id)}}}if(view==='plan'&&!$('#job-dialog').open)render()}if(e.key==='ahmad-workspace'&&!failedKeys.has('workspace')){syncWorkspace();if($('#job-dialog').open&&dialogJob){const button=$('#job-dialog [data-save]'),status=$('#job-dialog [data-status]');if(button)button.textContent=saved.includes(dialogJob.id)?'Remove from saved':'Save opportunity';if(status)status.value=states[dialogJob.id]||'Not started'}if(['saved','plan','shortlist','live'].includes(view)&&!$('#job-dialog').open)render()}});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'search_researched_opportunities',title:'Search current researched opportunities',description:'Read the existing researched shortlist by text. Does not fetch, apply or send data.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200||Object.keys(input).some(k=>k!=='query'))throw Error('Provide only a query of at most 200 characters.');const q=input.query.toLowerCase();return D.jobs.filter(j=>[j.title,j.company,j.summary].join(' ').toLowerCase().includes(q)).map(({title,company,location,rank,url,fit,closes,posted,researchCheckedAt})=>({title,company,location,rank,url,fit,closes,posted,researchCheckedAt:researchCheckedAt||D.checkedAt,evidenceNotice:'Dated research; confirm worksite, requirements and current availability with the employer.'}))}})}catch{}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&view==='plan'&&!$('#job-dialog').open)render()});
workspaceAction(retainKnownJobs);
render();
